<?php
require_once 'config.php';require_login();$pdo=db();$page_title='Deliveries';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$agent=(int)($_POST['agent_id']??0);$name=trim($_POST['customer_name']??'');$kg=(float)($_POST['package_kg']??0);$qty=(int)($_POST['quantity']??0);$price=(float)($_POST['price_per_kg']??0);$status=$_POST['status']??'Delivered';if($agent<1||$name===''||!in_array($kg,[1.0,5.0,20.0],true)||$qty<1||$price<0||!in_array($status,['Delivered','Pending','Cancelled'],true))throw new RuntimeException('Complete the required fields with valid values.');$stmt=$pdo->prepare("INSERT INTO deliveries(agent_id,customer_name,customer_phone,package_kg,quantity,price_per_kg,delivery_date,status,notes) VALUES(?,?,?,?,?,?,?,?,?)");$stmt->execute([$agent,$name,trim($_POST['customer_phone']??''),$kg,$qty,$price,$_POST['delivery_date']??date('Y-m-d'),$status,trim($_POST['notes']??'')]);redirect('deliveries.php');}catch(Throwable $ex){$error=$ex instanceof RuntimeException?$ex->getMessage():'Unable to save delivery.';}}
$agents=$pdo->query("SELECT id,name FROM agents WHERE status='Active' ORDER BY name")->fetchAll();$rows=$pdo->query("SELECT d.*,a.name AS agent_name FROM deliveries d JOIN agents a ON a.id=d.agent_id ORDER BY d.delivery_date DESC,d.id DESC")->fetchAll();require 'includes/header.php';?><div class="shell"><?php require 'includes/sidebar.php';?><main class="main"><?php require 'includes/topbar.php';?><div class="content"><div class="page-heading"><div><div class="eyebrow">CUSTOMER ORDERS</div><h1>Deliveries</h1><p>Log each customer delivery. Delivered orders are included in sales totals.</p></div></div><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?>
<div class="panel"><div class="panel-head"><h2>Record a delivery</h2></div><div class="panel-body"><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="field"><label>Agent *</label><select name="agent_id" required><option value="">Choose agent</option><?php foreach($agents as $a):?><option value="<?=$a['id']?>"><?=e($a['name'])?></option><?php endforeach;?></select></div><div class="field"><label>Customer name *</label><input name="customer_name" required maxlength="120"></div><div class="field"><label>Customer phone</label><input name="customer_phone" maxlength="40"></div><div class="field"><label>Packaging *</label><select name="package_kg" required><option value="20">20 KG — Sack</option><option value="5">5 KG — Big plastic</option><option value="1">1 KG — Small plastic</option></select></div><div class="field"><label>Quantity (packages) *</label><input type="number" name="quantity" min="1" required></div><div class="field"><label>Price per KG (₱) *</label><input type="number" name="price_per_kg" min="0" step="0.01" required></div><div class="field"><label>Delivery date *</label><input type="date" name="delivery_date" value="<?=date('Y-m-d')?>" required></div><div class="field"><label>Status</label><select name="status"><option>Delivered</option><option>Pending</option><option>Cancelled</option></select></div><div class="field full"><label>Notes</label><input name="notes" maxlength="255"></div><div class="field full"><button class="btn">＋ Save delivery</button><p class="help">Sales total = package KG × quantity × price per KG. Inventory deductions are shown as a simple total estimate and are not enforced per agent/package size.</p></div></form></div></div>
<div class="panel"><div class="panel-head"><h2>Delivery history <span class="badge"><?=count($rows)?> records</span></h2></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Customer</th><th>Agent</th><th>Package</th><th>Qty</th><th>Price/KG</th><th>Total</th><th>Status</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="8" class="empty">No deliveries recorded.</td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td><?=e($r['delivery_date'])?></td><td><?=e($r['customer_name'])?><br><small><?=e($r['customer_phone']?:'')?></small></td><td><?=e($r['agent_name'])?></td><td><?=e($r['package_kg'])?> KG</td><td><?=e($r['quantity'])?></td><td><?=money($r['price_per_kg'])?></td><td><strong><?=money($r['package_kg']*$r['quantity']*$r['price_per_kg'])?></strong></td><td><span class="badge <?=$r['status']==='Pending'?'gold':($r['status']==='Cancelled'?'red':'')?>"><?=e($r['status'])?></span></td></tr><?php endforeach;?></tbody></table></div></div>
</div><?php require 'includes/footer.php';?></main></div>
